import {GEAR,STYLES,RECIPES} from './data.js';
import {assemblyDiagram} from './assembly-diagram.js';
import {PARTS,ownerOf,assemblyItems,assemblyError,repairQuote} from './tackle.js';
import {TRAINING,TIER_POINTS,rodPoints,rodTier,rodRisk,trainingQuote} from './training.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gear=id=>GEAR.find(g=>g.id===id),money=n=>'€ '+new Intl.NumberFormat('nl-NL',{maximumFractionDigits:2}).format(n);
export const assemblyDraftFrom=p=>p?{id:p.id,name:p.name,rod:{...p.rod},items:{...p.items}}:null;
export function draftWithRod(game,draft,itemId){
 const items={...draft.items},item=game.state.tackleItems.find(i=>i.id===itemId),chosen=gear(item?.gearId);
 if(!chosen||chosen.category!=='rod')return {...draft,items:{...items,rod:null}};
 const method=chosen.style,rod={...draft.rod,style:method,rod:chosen.id};items.rod=item.id;
 if(method!==draft.rod.style){rod.bait=method==='karper'?'corn':method==='zee'?'squid':'maggots';rod.combo='none';}
 for(const part of PARTS.filter(p=>p!=='rod')){
  const compatible=unit=>{const g=gear(unit?.gearId);return g&&g.category===part&&(g.style==='all'||g.style===method)&&g.level<=game.level&&!ownerOf(game.state,unit.id,draft.id)&&unit.condition>0;};
  const current=game.state.tackleItems.find(i=>i.id===items[part]);
  const replacement=compatible(current)?current:game.state.tackleItems.find(i=>compatible(i)&&i.gearId===rod[part])||game.state.tackleItems.find(compatible);
  items[part]=replacement?.id||null;rod[part]=replacement?.gearId||(part==='indicator'?null:part==='line'?'line_field':part==='hook'?(method==='dobber'?'hook_16':'hook_12'):`${method}_${part}_field`);
 }
 return {...draft,rod,items};
}
export function academyCard(game,rods){const q=trainingQuote(game.level,rods);return `<section class="panel academy-card"><div class="academy-main"><div><span class="eyebrow">VISACADEMIE · LEVEL ${game.level}</span><h2>Je scholingscapaciteit</h2><p>Elke ingezette hengel gebruikt punten. Het hoogste niveau van hengel of molen bepaalt de belasting.</p></div><strong class="${q.allowed?'':'danger-text'}">${q.used}<small> / ${q.capacity}</small></strong></div><div class="progress-track"><i style="width:${Math.min(100,q.used/q.capacity*100)}%"></i></div><div class="academy-tiers">${TIER_POINTS.map((n,i)=>`<span>T${i+1}<b>${n} pt</b></span>`).join('')}</div>${!q.allowed?`<p class="notice">Deze combinatie vraagt level ${q.requiredLevel}. Kies lichtere hengels of minder lijnen.</p>`:''}<details><summary>Bekijk je opleiding en volgende lessen</summary><div class="academy-lessons">${TRAINING.map(t=>`<div class="${game.level>=t.level?'learned':''}"><span>LV ${t.level}</span><strong>${t.name}</strong><b>${t.points} pt</b></div>`).join('')}</div></details></section>`;}
function choices(game,draft,field){
 const r=draft.rod;
 if(PARTS.includes(field)){
  const items=game.state.tackleItems.filter(i=>gear(i.gearId).category===field&&(field==='rod'||gear(i.gearId).style==='all'||gear(i.gearId).style===r.style));
  return [{id:'',name:field==='indicator'?'Standaardsignaal':'Kies een vrij onderdeel'},...items.map(item=>{const g=gear(item.gearId),owner=ownerOf(game.state,item.id,draft.id),current=draft.items[field]===item.id;return {id:item.id,name:`${g.name} · ${item.id.split('_').at(-1)}${owner?' · bezet door '+owner.name:item.condition<=0?' · gebroken':g.category==='rod'?' · '+Math.round(item.condition)+'%':' · vrij'}`,disabled:!!owner||g.level>game.level||item.condition<=0&&!current};})];
 }
 return [{id:'',name:'Geen extra rig'},...RECIPES.filter(r=>r.level<=game.level).map(r=>{const held=game.state.rodPresets.filter(p=>p.id!==draft.id&&p.assembled&&p.rod.crafted===r.id).length,free=(game.state.crafted[r.id]||0)-held;return {id:r.id,name:`${r.name} · ${free} vrij`,disabled:free<1};})];
}
function partSelect(game,draft,field,label,number){const selected=PARTS.includes(field)?draft.items[field]||'':draft.rod[field]||'',items=choices(game,draft,field);return `<label class="assembly-part field part-${field}" data-component="${field}"><span><i>${number}</i>${label}</span><select id="assembly-part-${field}" data-assembly-field="${field}" aria-label="${label}">${items.map(o=>`<option value="${esc(o.id)}" ${o.id===selected?'selected':''} ${o.disabled?'disabled':''}>${esc(o.name)}</option>`).join('')}</select></label>`;}
export function assemblyWorkshop(game,draft,slot=0){
 const r=draft.rod,existing=game.state.rodPresets.find(p=>p.id===draft.id),busy=existing&&game.assemblyBusy(existing.id),allocation=assemblyItems(game.state,r,draft.id,draft.items),error=game.validRod(r,{includeBait:false})||allocation.error,risk=rodRisk({...r,baitSize:'normal'}),rodItem=game.state.tackleItems.find(i=>i.id===draft.items.rod),repair=repairQuote(game.state,rodItem?.id);
 const catalog=game.state.rodPresets.map(p=>{const item=game.state.tackleItems.find(i=>i.id===p.items?.rod),selected=game.state.selectedRods.some(r=>r.sourcePresetId===p.id);return `<article class="assembled-card ${p.id===draft.id?'selected':''}" data-assembly-card="${esc(p.id)}"><button class="assembly-open" data-edit-assembly="${esc(p.id)}"><strong data-user-text>${esc(p.name)}</strong><span>${STYLES.find(s=>s.id===p.rod.style)?.name} · T${rodTier(p.rod)+1} · ${rodPoints(p.rod)} pt</span><small>${!p.assembled?'Nog te bouwen':item?.condition===0?'Gebroken':Math.round(item?.condition??100)+'% conditie'}${game.assemblyBusy(p.id)?' · IN GEBRUIK':''}</small></button>${selected?'<p>Gekozen voor je sessie</p>':''}</article>`;}).join('');
 return `<div class="assembly-workshop"><aside class="panel assembly-library"><div class="panel-head"><h2>Mijn gebouwde hengels</h2><span>${game.state.rodPresets.length} / 120</span></div><div class="assembly-library-list">${catalog||'<p>Nog geen opgeslagen hengels.</p>'}</div><button class="primary" data-action="new-assembly">Nieuwe hengel bouwen</button><p>Bewaar hier losse hengelpresets. Bij Plan je sessie kies je welke hengels meegaan.</p></aside><section class="panel assembly-editor"><div class="panel-head"><div><span class="eyebrow">BOUW JE EIGEN HENGEL</span><h2>${existing?'Hengel aanpassen':'Nieuwe hengel'}</h2></div><span class="tag">T${rodTier(r)+1} · ${rodPoints(r)} pt</span></div><div class="assembly-name-row"><label class="field"><span>NAAM VAN JE HENGEL</span><input id="assembly-name" maxlength="45" value="${esc(draft.name)}" data-user-text aria-label="Naam van je hengel"></label><div class="assembly-method"><span>VISMETHODE</span><strong data-assembly-method>${rodItem?STYLES.find(s=>s.id===r.style)?.name:'Kies eerst een hengel'}</strong><small>Wordt bepaald door je hengel</small></div></div>${busy?'<div class="notice">Deze hengel vist nu. Je kunt hem aanpassen zodra de sessie is beëindigd.</div>':''}<fieldset class="assembly-controls" ${busy?'disabled':''}><legend class="sr-only">Onderdelen van je hengel</legend><div class="assembly-stage">${assemblyDiagram(r)}<p class="assembly-drawing-help">Klik op een genummerd onderdeel om de bijbehorende keuze te openen.</p></div><div class="assembly-component-grid">${partSelect(game,draft,'rod','HENGEL','01')}${partSelect(game,draft,'reel','MOLEN','02')}${partSelect(game,draft,'line','HOOFDLIJN','03')}${partSelect(game,draft,'indicator','BEETMELDER','04')}${partSelect(game,draft,'terminal',r.style==='feeder'?'VOERKORF / MONTAGE':r.style==='dobber'?'DOBBER / LOOD':'LOOD / MONTAGE','05')}${partSelect(game,draft,'hook','HAAK','06')}</div><div class="assembly-extra assembly-hardware-extra">${partSelect(game,draft,'crafted','ZELFGEMAAKTE RIG','07')}</div></fieldset><div class="assembly-safety"><div><span>CONDITIE</span><strong>${Math.round(rodItem?.condition??100)}%</strong></div><div><span>HENGELGRENS</span><strong>${risk.rating} kg</strong></div><div><span>VEILIGE SETGRENS</span><strong>${Number(risk.safe.toFixed(1))} kg</strong></div><div><span>WORPSCHADEKANS</span><strong>${Number((risk.chance*100).toFixed(1))}%</strong></div></div>${risk.chance?'<p class="assembly-warning">Deze haak overbelast de hengel. Je riskeert schade en uiteindelijk breuk. Kies lichter materiaal of een sterkere hengel.</p>':'<p class="assembly-note">Deze montage geeft geen extra worpschade. Een te zware vis aan een sterke lijn kan de hengel alsnog beschadigen.</p>'}<p class="assembly-note">Hengel, molen, lijn, haak, montage en beetmelder zijn bezet zodra je opslaat. Aas, aasgrootte en liquid kies je per hengel bij Plan je sessie.</p>${error?`<p class="assembly-warning" role="status">${esc(error)}</p>`:''}<div class="assembly-actions">${existing?`<button class="button danger" data-dismantle-assembly="${esc(existing.id)}" ${busy?'disabled':''}>Uit elkaar halen</button>`:''}${repair?.missing>0?`<button class="button" data-repair-rod="${esc(rodItem.id)}" ${busy||game.state.money<repair.cost?'disabled':''}>Repareren · ${repair.cost?money(repair.cost):'gratis'}</button>`:''}<button class="button" data-page="shop">Onderdelen kopen</button><button class="primary" data-action="save-assembly" ${busy||error?'disabled':''}>${existing?'Hengel bijwerken':'Hengel bouwen & opslaan'}</button></div></section></div>`;
}
export function repairInventory(game){const damaged=game.state.tackleItems.filter(i=>gear(i.gearId).category==='rod'&&i.condition<100);return `<section class="panel repair-inventory"><div class="panel-head"><h2>Reparatiewerkplaats</h2><span>${damaged.length}</span></div><div class="panel-body">${damaged.map(item=>{const q=repairQuote(game.state,item.id),owner=ownerOf(game.state,item.id);return `<div class="repair-row"><div><strong>${esc(gear(item.gearId).name)}</strong><small>${owner?esc(owner.name):'Los onderdeel'} · ${Math.round(item.condition)}% · ${item.starter?'Starterhengel':'Gekocht materiaal'}</small></div><button class="button" data-repair-rod="${esc(item.id)}" ${owner&&game.assemblyBusy(owner.id)||game.state.money<q.cost?'disabled':''}>Repareren · ${q.cost?money(q.cost):'gratis'}</button></div>`;}).join('')||'<p>Al je hengels zijn in goede staat.</p>'}<p class="subtle">Je oorspronkelijke starterhengels herstel je gratis. Gekochte hengels kosten maximaal 35% van de nieuwprijs om te repareren.</p></div></section>`;}
